  _walk(prefix) {
    let node = this.root;
    for (const c of prefix) {
      if (!node.children.has(c)) return null;
      node = node.children.get(c);
    }
    return node;
  }

  search(word)          { const n = this._walk(word);   return n !== null && n.isEnd; }
  startsWith(prefix)    { return this._walk(prefix) !== null; }
}
