* its water level is capped by its own maximum, since the other side is at least as tall. */
public final class RainWater {
private RainWater() {}
public static long trap(int[] height) {
if (height == null) throw new IllegalArgumentException("no heights");
for (int h : height)
if (h < 0) throw new IllegalArgumentException("a height can't be negative: " + h);
int left = 0, right = height.length - 1;
long leftMax = 0, rightMax = 0, water = 0;
// long: the total can pass int
while (left < right) {
if (height[left] < height[right]) {
leftMax = Math.max(leftMax, height[left]);
water += leftMax - height[left];
left++;
} else {
rightMax = Math.max(rightMax, height[right]);
water += rightMax - height[right];
right--;
}
}
return water;
}
}

