FrontOrBack.java · compiles for Java 8, tested on JDK 11, 21 and 25
/** The largest sum from taking exactly k values, each from the front or the back of the array.
* Every choice is "i from the front and k - i from the back", so start with the first k and
* trade one front value for one back value at a time: O(k) time, O(1) memory. */
public final class FrontOrBack {
private FrontOrBack() {}
public static long maxSum(int[] a, int k) {
if (a == null || k < 0 || k > a.length)
throw new IllegalArgumentException("need an array and 0 <= k <= its length");
long sum = 0;
for (int i = 0; i < k; i++) sum += a[i];
// all k from the front
long best = sum;
for (int i = 1; i <= k; i++) {
// now k - i from the front
sum += (long) a[a.length - i] - a[k - i];
// and i from the back
best = Math.max(best, sum);
}
return best;
}
}

