/** Container with most water: two pointers from both ends. The area between walls i and j is
* (j - i) * min(h[i], h[j]); moving the taller wall inward can only shrink the width without
* raising the lower wall, so always move the shorter one. O(n) time, O(1) memory. */
public final class MostWater {
private MostWater() {}
public static long maxArea(int[] height) {
if (height == null) throw new IllegalArgumentException("no heights");
for (int h : height)
if (h < 0) throw new IllegalArgumentException("a height can't be negative: " + h);
int i = 0, j = height.length - 1;
long best = 0;
// long: width * height can pass int
while (i < j) {
long area = (long) (j - i) * Math.min(height[i], height[j]);
best = Math.max(best, area);
if (height[i] < height[j]) i++;
// the shorter wall limits the area
else j--;
}
return best;
}
}

