/** Players take turns removing a number from either end; both play perfectly. margin(i, j),
* the most the player to move can win by on a[i..j], is the better of a[i] - margin(i+1, j)
* and a[j] - margin(i, j-1). One row of longs: O(n^2) time, O(n) memory, no overflow. */
public final class PredictTheWinner {
private PredictTheWinner() {}
public static boolean firstPlayerWins(int[] a) {
return margin(a) >= 0;
}

// a tie counts as a win

public static long margin(int[] a) {
if (a == null || a.length == 0) throw new IllegalArgumentException("need numbers");
int n = a.length;
long[] m = new long[n];
// m[j] = margin(i, j)
for (int i = n - 1; i >= 0; i--) {
m[i] = a[i];
// one number: take it
for (int j = i + 1; j < n; j++)
// m[j] holds margin(i+1, j)
m[j] = Math.max(a[i] - m[j], a[j] - m[j - 1]);
}
return m[n - 1];
}
}

