    int getX() { return x; }
    int getY() { return y; }

    Point withX(int newX) { return new Point(newX, y); }
    Point plus(Point other) { return new Point(x + other.x, y + other.y); }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

