const unique2 = arr => arr.filter((v, i) => arr.indexOf(v) === i);
```

### 5. Count character occurrences
```javascript
function countChars(str) {
  return [...str].reduce((acc, ch) => {
    acc[ch] = (acc[ch] || 0) + 1;
    return acc;
  }, {});
}
