### 7. Flatten a nested array
```javascript
const flat = arr => arr.flat(Infinity);
// By hand:
function flatten(arr) {
  return arr.reduce((acc, v) =>
    acc.concat(Array.isArray(v) ? flatten(v) : v), []);
}
